build=r'''#!/usr/bin/env node
import crypto from'node:crypto';import fs from'node:fs';import path from'node:path';import{fileURLToPath}from'node:url';const R=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p),'utf8')),b=p=>fs.readFileSync(path.join(R,p)),J=(p,v)=>{let t=path.join(R,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,JSON.stringify(v,null,2)+'\n')},W=(p,v)=>{let t=path.join(R,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,v)},H=v=>crypto.createHash('sha256').update(v).digest('hex');
export const scope=['.github/workflows/counter-selector-wave-07.yml','data/project/counter-selector-wave-07-batch-02.json','data/project/counter-selector-wave-07-source-registry.json','schemas/counter-selector-wave-07-acquisition.schema.json','docs/methods/counter-selector-wave-07-acquisition.md','docs/milestones/counter-selector-wave-07.md','tools/build-counter-selector-wave-07.mjs','tools/validate-counter-selector-wave-07.mjs','test/counter-selector-wave-07.test.js'];
export function manifest(){let e=scope.map(p=>{let x=b(p);return{path:p,sha256:H(x),bytes:x.length}});return{schema_version:'counter-selector-wave-07-release-manifest@1',program_id:'counter-selector-v1',wave_id:'CS-W07-B02',as_of:'2026-07-31',hash_mode:'sha256_exact_bytes',scope_ordered:true,self_included:false,entries:e,combined_sha256:H(e.map(x=>`${x.path}\0${x.sha256}\0${x.bytes}\n`).join('')),boundaries:{exact_bytes_prove_source_truth:false,manifest_proves_operator_capacity:false,manifest_authorizes_field_test:false,manifest_authorizes_ranking:false,manifest_authorizes_graph_edge:false,graph_effect:'none'}}}
export function acquisition(c){let records=c.candidate_results.map(x=>({schema_version:'counter-selector-artifact-acquisition-b02@1',program_id:c.program_id,wave_id:c.wave_id,batch_id:c.batch_id,candidate_id:x.candidate_id,blind_token:x.blind_token,denominator_class:x.denominator_class,public_label:x.public_label,source_record_id:x.source_record_id,source_ids:[...x.source_ids],source_packet_count:x.source_ids.length,acquisition_state:x.acquisition_state,qualification:x.qualification,artifact_summary:x.artifact_summary,missing_receipts:[...x.missing_receipts],falsifier:x.falsifier,blind_packet_ready:!!x.blind_packet,blind_review_executed:false,field_test_eligible:false,operator_finding:false,promotion_generated:false,person_ranking_generated:false,public_identity_release_authorized:false,graph_effect:'none'}));return{schema_version:'counter-selector-artifact-acquisition-b02-registry@1',program_id:c.program_id,wave_id:c.wave_id,batch_id:c.batch_id,as_of:c.as_of,status:'batch_02_acquired_four_packets_ready_review_not_started',parent_release_sha256:c.parent_release_sha256,counts:structuredClone(c.expected_counts),records,next_action:'Run blind-first review on four packets; preserve attribution class and do not convert system mechanisms into people or partnerships.',boundaries:structuredClone(c.boundaries)}}
export function packets(c){let p=c.candidate_results.filter(x=>x.blind_packet).map(x=>({...structuredClone(x.blind_packet),schema_version:'counter-selector-blind-packet-b02@1',program_id:c.program_id,wave_id:c.wave_id,batch_id:c.batch_id,blind_token:x.blind_token,identity_removed:true,status_cues_removed:true,source_ids_removed:true,denominator_class_removed:true,blind_review_executed:false,field_test_authorized:false,operator_finding:false,public_identity_release_authorized:false,graph_effect:'none',packet_state:'identity_minimized_ready_not_reviewed'}));return{schema_version:'counter-selector-blind-packet-b02-registry@1',program_id:c.program_id,wave_id:c.wave_id,batch_id:c.batch_id,as_of:c.as_of,status:'four_identity_minimized_packets_ready_review_not_started',counts:{packets_ready:p.length,person_attributable_packets:p.filter(x=>x.attribution_class.startsWith('person_attributable')).length,system_mechanism_packets:p.filter(x=>x.attribution_class==='system_mechanism').length,blind_reviews_executed:0,field_tests_executed:0,operator_findings:0,promotions:0,person_rankings:0,public_identity_releases:0,graph_effects:0},private_map:c.candidate_results.filter(x=>x.blind_packet).map(x=>({packet_id:x.blind_packet.packet_id,blind_token:x.blind_token,candidate_id:x.candidate_id,mapping_authority:'custody_only_not_available_to_blind_reviewer'})),packets:p,next_action:'Assign artifact-validity and adversarial-countermodel passes without identity, class, status, institution, or source route.',boundaries:{packet_is_operator_finding:false,packet_is_review_result:false,system_mechanism_is_person_or_partnership:false,private_map_available_to_reviewer:false,packet_authorizes_field_test:false,graph_effect:'none'}}}
const E=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
export function report(c,s,a,p,m){return{schema_version:'counter-selector-wave-07-report@1',program_id:c.program_id,wave_id:c.wave_id,batch_id:c.batch_id,as_of:c.as_of,title:c.title,status:a.status,parent_release_sha256:c.parent_release_sha256,counts:a.counts,qualification_counts:{partial_not_blind_ready:a.records.filter(x=>x.qualification==='partial_not_blind_ready').length,qualifying_for_blind_packet:a.records.filter(x=>x.qualification==='qualifying_for_blind_packet').length},packet_attribution_counts:p.counts,records:a.records.map(x=>({candidate_id:x.candidate_id,denominator_class:x.denominator_class,public_label:x.public_label,qualification:x.qualification,source_packet_count:x.source_packet_count,blind_packet_ready:x.blind_packet_ready,graph_effect:x.graph_effect})),packet_summaries:p.packets.map(x=>({packet_id:x.packet_id,attribution_class:x.attribution_class,task:x.task,observable_transition:x.observable_transition,blind_review_executed:false,field_test_authorized:false,graph_effect:'none'})),next_action:a.next_action,boundaries:{...c.boundaries,...s.boundaries,...p.boundaries},release_manifest:{path:'data/project/counter-selector-wave-07-release-manifest.json',combined_sha256:m.combined_sha256}}}
export function html(r){let rows=r.records.map(x=>`<tr><td><code>${E(x.candidate_id)}</code></td><td>${E(x.denominator_class)}</td><td>${E(x.qualification)}</td><td>${x.source_packet_count}</td><td>${x.blind_packet_ready}</td></tr>`).join('');return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Counter-Selector Wave 07</title><style>body{max-width:1300px;margin:auto;padding:40px 24px;font:16px/1.55 system-ui;background:#f1eee7;color:#171714}h1{font-size:4rem}.state{font-weight:900;color:#7b2e1d}table{width:100%;background:#fff;border-collapse:collapse}td,th{padding:10px;border:1px solid #ddd}.boundary{margin-top:25px;padding:18px;border-left:7px solid #7b2e1d;background:#fff;white-space:pre-wrap}</style></head><body><h1>Four packets, two explicit partials</h1><p class="state">6 OBJECTS · 13 OFFICIAL PACKETS · 4 BLIND PACKETS · 0 FIELD TESTS</p><table><thead><tr><th>Object</th><th>Class</th><th>Qualification</th><th>Sources</th><th>Packet</th></tr></thead><tbody>${rows}</tbody></table><div class="boundary">official summary ≠ original work object\ncatastrophe ≠ person-level operator proof\naudit output ≠ support-adjusted surplus\npolicy authority ≠ repair-capable partnership\nsystem mechanism ≠ person</div><p>${E(r.next_action)}</p><code>${r.release_manifest.combined_sha256}</code></body></html>\n`}
export function build(){let c=read('data/project/counter-selector-wave-07-batch-02.json'),s=read('data/project/counter-selector-wave-07-source-registry.json'),a=acquisition(c),p=packets(c);J('data/project/counter-selector-artifact-acquisition-b02-registry.json',a);J('data/project/counter-selector-blind-packet-b02-registry.json',p);let m=manifest();J('data/project/counter-selector-wave-07-release-manifest.json',m);let r=report(c,s,a,p,m);J('reports/core-thesis/counter-selector-wave-07/data.json',r);W('reports/core-thesis/counter-selector-wave-07/index.html',html(r));console.log('wave07',m.combined_sha256)}if(process.argv[1]===fileURLToPath(import.meta.url))build();
'''
W('tools/build-counter-selector-wave-07.mjs',build)
